import{_ as e,c as t,o,a4 as a}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q22：React 18 的重要新特性","description":"","frontmatter":{},"headers":[],"relativePath":"react/q22.md","filePath":"react/q22.md","lastUpdated":null}'),r={name:"react/q22.md"},s=a('<h1 id="q22-react-18-的重要新特性" tabindex="-1">Q22：React 18 的重要新特性 <a class="header-anchor" href="#q22-react-18-的重要新特性" aria-label="Permalink to &quot;Q22：React 18 的重要新特性&quot;">​</a></h1><ol><li><strong>自动批处理</strong>：不仅事件处理，setTimeout、Promise 等多次 setState 也会合并为一次渲染。</li><li><strong>并发特性</strong>：<code>startTransition</code> 将更新标记为低优先级，<code>useTransition</code> 返回 pending 状态。</li><li><strong><code>useDeferredValue</code></strong>：延迟更新某个值，让出主线程给高优先级更新。</li><li><strong><code>useId</code></strong>：生成跨服务端和客户端一致的唯一 ID。</li><li><strong>新的 Suspense</strong>：支持服务端流式渲染和选择性注水。</li><li><strong>并发渲染</strong>：React 可以中断渲染，优先更新高优先级部分，保持 UI 响应。</li></ol>',2),n=[s];function c(i,l,d,_,g,p){return o(),t("div",null,n)}const h=e(r,[["render",c]]);export{m as __pageData,h as default};
